mapper.select:
SELECT
e.ledger_entry_id,
      e.transfer_id,
      t.transfer_type,
      e.entry_type,
      e.amount,
      e.balance_after,
      t.memo,
      e.created_at
  FROM wallet_ledger_entries e
  JOIN wallet_transfers t ON t.transfer_id = e.transfer_id
  WHERE e.wallet_id = #{walletId}
AND e.deleted_at IS NULL

    AND e.ledger_entry_id < #{cursor}


    AND t.transfer_type = #{type}


    AND t.transfer_status = #{status}


    AND e.created_at >= #{from}


    AND e.created_at < #{to}

ORDER BY e.ledger_entry_id DESC
LIMIT #{limit}
